s.linregress(np.log(df_log.ad_spend_usd), np.log(df_log.sales_revenue_usd))\nprint(f'Elasticity: {m:.4f}')\nprint(f'R2 (log-log): {r**2:.4f}')\nprint(f'p-value: {p:.4e}')\nprint()\nprint('=== HOLIDAY EFFECT ===')\nhol = df[df.is_holiday_month==1]['sales_revenue_usd']\nnon_hol = df[df.is_holiday_month==0]['sales_revenue_usd']\nprint(f'Holiday avg sales: {hol.mean():.2f}')\nprint(f'Non-holiday avg sales: {non_hol.mean():.2f}')\nt, p = stats.ttest_ind(hol, non_hol)\nprint(f'T-test p-value: {p:.4f}')\nprint()\nprint('=== BUDGET RECOMMENDATION ===')\nmedian_share = df['implied_share'].median()\nlatest_month = df['date'].max()\nlatest_sales = df[df['date']==latest_month]['sales_revenue_usd'].sum()\nbase_budget = latest_sales * median_share\nprint(f'Latest month: {latest_month}')\nprint(f'Latest total sales: {latest_sales:.2f}')\nprint(f'Base monthly budget: {base_budget:.2f}')\nprint(f'Annual budget (flat): {base_budget*12:.2f}')\nmonthly_avg = df.groupby('month')['sales_revenue_usd'].mean()\nmonthly_idx = monthly_avg / monthly_avg.mean()\nfor m in range(1,13):\n    adj = float(monthly_idx.get(m, 1.0))\n    print(f'  Month {m:2d}: {base_budget*adj:.2f}')\n\" > outputs/detailed_stats.txt 2>&1"
